#!/usr/bin/env bash
# Terminal matrix driver: measures one terminal mode under a nested `crucible --winit`.
# Adapted from the 2026-11 terminal spike script (an internal note, not published).
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'docs/spikes/terminal-matrix/matrix.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'matrix.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -euo pipefail

here=$(cd "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")" && pwd)
repo=$(cd "$here/../../.." && pwd)
# shellcheck source=../../../scripts/lib/build-id.sh
. "$repo/scripts/lib/build-id.sh"

MODES="cterm cterm-daemon foot foot-server urxvt urxvt-daemon"

usage() {
	cat <<USAGE
Usage: matrix.sh [--help|-h] [--build|--version] <mode>...
       matrix.sh table [OUT_DIR]

Measure terminal modes under a nested crucible --winit (started with
\`crucible msg run-on scratch-41-wp1 <script>\`, never in the focused workspace).
Modes: $MODES   (ghostty is not installed; not measured)

Per mode: spawn-to-first-frame latency (cold and warm, n=RUNS), PSS with 1, 5 and 10
windows (daemon modes: server + clients), idle CPU over 60 s with 5 windows, throughput of
a 50 MB cat (n=3), first-frame latency of a new window while another floods output
(n=3), and integration checks (exec flag, cwd, {gap} argument, restore after a nested
restart, overlay host). Results: \$OUT/<mode>.res (key=value lines) and \$OUT/<mode>.log.
\`table\` renders the .res files as markdown.

First-frame method: the compositor's own "latency: spawn->map" line (ms, 1 ms resolution)
for every mode, read from the nested compositor log.

Environment: OUT (default: the gitignored spike scratch dir in this checkout), BIN (default target/release/crucible),
RUNS (default 5), T (scratch dir, default /tmp/cde-41wp1; keep it short: SUN_LEN),
WS (scratch workspace, default scratch-41-wp1), LOAD_MAX (default 2.0).
Runs serialize on \$OUT/lock (flock). A sample taken while the 1-min load average exceeds
LOAD_MAX is discarded and repeated; the discard count is recorded.
USAGE
}

case " $* " in *" --help "* | *" -h "*) usage; exit 0 ;; esac
build_flags "${BASH_SOURCE[0]}" "$@"

OUT=${OUT:-$repo/runs/spike/terminal-matrix/out}
BIN=${BIN:-$repo/target/release/crucible}
RUNS=${RUNS:-5}
T=${T:-/tmp/cde-41wp1}
WS=${WS:-scratch-41-wp1}
LOAD_MAX=${LOAD_MAX:-2.0}
PARENT_WL=${XDG_RUNTIME_DIR:-/run/user/$(id -u)}/${WAYLAND_DISPLAY:-wayland-1}
CTERM_BIN=${CTERM_BIN:-$(command -v cterm || true)}
FOOT_BIN=${FOOT_BIN:-$(command -v foot || true)}
FOOTCLIENT_BIN=${FOOTCLIENT_BIN:-$(command -v footclient || true)}
URXVT_BIN=${URXVT_BIN:-/usr/bin/urxvt}
URXVTD_BIN=${URXVTD_BIN:-/usr/bin/urxvtd}
URXVTC_BIN=${URXVTC_BIN:-/usr/bin/urxvtc}

strip_ansi() { sed 's/\x1b\[[0-9;]*m//g'; }
msg() { CDE_SOCKET=$T/run/cde/wayland-1.sock "$BIN" msg "$@"; }
median() { sort -n | awk '{a[NR]=$1} END{ if(NR==0){print "NA"} else if(NR%2){print a[(NR+1)/2]} else {printf "%.1f\n",(a[NR/2]+a[NR/2+1])/2} }'; }
minmax() { sort -n | awk 'NR==1{lo=$1} {hi=$1} END{ if(NR==0) print "NA"; else printf "%s-%s", lo, hi }'; }
res() { printf '%s=%s\n' "$1" "$2" >>"$OUT/$MODE.${RESEXT:-res}"; echo "RES $1=$2" | tee -a "$OUT/$MODE.log"; }
log() { echo "$*" | tee -a "$OUT/$MODE.${LOGEXT:-log}"; }
load1() { cut -d' ' -f1 /proc/loadavg; }
over_load() { awk -v l="$(load1)" -v m="$LOAD_MAX" 'BEGIN{exit !(l>m)}'; }

DISCARDS=0
LOAD_OVER_ACCEPTED=0
# wait until the 1-min load average is within LOAD_MAX; each wait round counts as one discarded sample
gate_load() {
	local i=0
	while over_load; do
		DISCARDS=$((DISCARDS + 1)); i=$((i + 1))
		[ "$i" -gt "${LOAD_WAIT_ROUNDS:-6}" ] && { LOAD_OVER_ACCEPTED=$((LOAD_OVER_ACCEPTED + 1)); log "load1 $(load1) still > $LOAD_MAX after $i waits (wait limit); sample taken anyway and flagged"; return 0; }
		sleep 10
	done
	return 0
}

# ---- /proc helpers (perl-base) -----------------------------------------------------------------
# procs <root pid>...: union of the process subtrees; prints "pss_kB rss_kB nprocs unreadable ticks"
procs() {
	perl -e '
	my %kids; opendir(D,"/proc"); for my $p (grep /^\d+$/, readdir D){ open(F,"<","/proc/$p/stat") or next; my $s=<F>; close F; $s=~/^\d+ \(.*\) \S (\d+)/ or next; push @{$kids{$1}},$p }
	my %seen; my @q=@ARGV; my ($pss,$rss,$n,$un,$tk)=(0,0,0,0,0);
	while(defined(my $p=shift @q)){ next if $seen{$p}++; push @q,@{$kids{$p}||[]};
	  open(F,"<","/proc/$p/stat") or next; my $s=<F>; close F; $n++;
	  $s=~/\) (.*)$/ and do { my @f=split / /,$1; $tk+=$f[11]+$f[12] };
	  if(open(F,"<","/proc/$p/status")){ while(<F>){ $rss+=$1 if /^VmRSS:\s+(\d+)/ } close F }
	  if(open(F,"<","/proc/$p/smaps_rollup")){ my $got=0; while(<F>){ if(/^Pss:\s+(\d+)/){$pss+=$1;$got=1} } close F; $un++ unless $got } else { $un++ } }
	print "$pss $rss $n $un $tk\n"' "$@"
}
# findproc <cmdline regex over NUL-joined argv>: pids whose environment has our XDG_RUNTIME_DIR
findproc() {
	perl -e '
	my ($re,$rd)=@ARGV; opendir(D,"/proc"); for my $p (grep /^\d+$/, readdir D){
	  open(F,"<","/proc/$p/cmdline") or next; local $/; my $c=<F>; close F; next unless defined $c; $c=~s/\0/ /g; next unless $c=~/$re/;
	  open(E,"<","/proc/$p/environ") or next; my $e=<E>; close E; print "$p\n" if defined $e && index($e,"XDG_RUNTIME_DIR=$rd\0")>=0 }' "$1" "$T/run"
}
alive_pids() { local p; for p in "$@"; do [ -d "/proc/$p" ] && echo "$p"; done; return 0; }
# all terminal roots currently counted for memory: window pids recorded by the wrapper (minus the
# overlay-host pids captured at startup) plus the mode's resident daemon/server pids
roots() {
	local p
	{ if [ "$NOWRAP" = 1 ]; then for p in $(findproc 'cterm -o'); do case " $OVL_PIDS $DAEMON_PID " in *" $p "*) ;; *) echo "$p" ;; esac; done
		else sed -n "$((OVL_N + 1)),\$p" "$T/pids" 2>/dev/null | while read -r p; do echo "$p"; done; fi
		[ -n "${DAEMON_PID:-}" ] && echo "$DAEMON_PID"; } | while read -r p; do [ -d "/proc/$p" ] && echo "$p"; done || true
}
procs_now() { local R; mapfile -t R < <(roots); procs "${R[@]}"; }
allpids() { if [ "$NOWRAP" = 1 ]; then findproc 'cterm -o'; else cat "$T/pids"; fi; }
# fmt_pss <pss> <unreadable> <nprocs>
fmt_pss() {
	if [ "$3" -eq 0 ]; then echo "0 (no process)"; elif [ "$2" -ge "$3" ]; then echo "n/a (setgid, unreadable)"
	elif [ "$2" -gt 0 ]; then echo "$1>= (lower bound; $2 of $3 procs unreadable)"; else echo "$1"; fi
}

# ---- mode definitions -------------------------------------------------------------------------
# sets: PROG PRE EXECF CWDF TARGS_KDL (terminal-args) DAEMON_KIND; ARGSTR (expected substituted arg)
define_mode() {
	DAEMON_KIND=none; PRE=""; EXTRA_ENV=""; NOWRAP=0
	case $MODE in
	cterm) PROG=$CTERM_BIN; PRE="--standalone"; EXECF=-e; CWDF="--working-directory"; TARGS='"-o" "pad={gap}x{gap} center"'; ARGLOG='"pad=9x9 center"'; VER=$("$PROG" --version) ;;
	cterm-daemon) PROG=$CTERM_BIN; NOWRAP=1; EXECF=-e; CWDF="--working-directory"; TARGS='"-o" "mode=daemon" "-o" "pad={gap}x{gap} center"'; ARGLOG='"pad=9x9 center"'; DAEMON_KIND=cterm; VER=$("$PROG" --version) ;;
	foot) PROG=$FOOT_BIN; EXECF=-e; CWDF="--working-directory"; TARGS='"-o" "pad={gap}x{gap} center"'; ARGLOG='"pad=9x9 center"'; VER=$("$PROG" --version) ;;
	foot-server) PROG=$FOOTCLIENT_BIN; PRE="--server-socket=$T/run/foot.sock"; EXECF=-e; CWDF="--working-directory"; TARGS='"-o" "pad={gap}x{gap} center"'; ARGLOG='"pad=9x9 center"'; DAEMON_KIND=foot; VER=$("$FOOT_BIN" --version) ;;
	urxvt) PROG=$URXVT_BIN; EXECF=-e; CWDF="-cd"; TARGS='"-b" "{gap}"'; ARGLOG='"-b", "9"'; VER=$("$PROG" -help 2>&1 | head -1 || true) ;;
	urxvt-daemon) PROG=$URXVTC_BIN; EXECF=-e; CWDF="-cd"; TARGS='"-b" "{gap}"'; ARGLOG='"-b", "9"'; DAEMON_KIND=urxvt; EXTRA_ENV="RXVT_SOCKET=$T/run/urxvtd.sock"; VER=$("$URXVT_BIN" -help 2>&1 | head -1 || true) ;;
	*) echo "unknown mode $MODE (modes: $MODES)" >&2; exit 2 ;;
	esac
	[ -n "$PROG" ] || { echo "binary for $MODE not found" >&2; exit 2; }
}

# write the wrapper `terminal` used by the nested compositor: records its pid and argv, optional
# per-run overrides in $T/over.env (cold daemon instance), then exec's the real terminal
write_wrapper() {
	printf '#!/bin/sh\npwd > "%s/cwd.out"; echo ok > "%s/exec.ok"\n' "$T" "$T" >"$T/exec.sh"
	printf '#!/bin/sh\ns=$(date +%%s%%N); cat "%s"; e=$(date +%%s%%N); echo $((e-s)) >> "%s/thr.txt"\n' "$OUT/50mb.txt" "$T" >"$T/thr.sh"
	printf '#!/bin/sh\ntimeout %s sh -c '"'"'while :; do cat "%s"; done'"'"'\ntouch "%s/flood.done"\n' "${FLOOD_S:-14}" "$OUT/50mb.txt" "$T" >"$T/flood.sh"
	chmod +x "$T/exec.sh" "$T/thr.sh" "$T/flood.sh"
	# cterm: its window grant binds to the spawned executable, so a wrapper script would be rejected;
	# the real binary is configured directly and window pids come from a /proc scan
	if [ "$NOWRAP" = 1 ]; then WRAP_PATH=$PROG; return 0; fi
	mkdir -p "$T/bin"; WRAP_PATH=$T/bin/$(basename "$PROG")
	cat >"$WRAP_PATH" <<WRAP
#!/bin/sh
D=$T
echo \$\$ >> "\$D/pids"
echo "\$*" >> "\$D/argv"
$([ -n "$EXTRA_ENV" ] && echo "export $EXTRA_ENV")
[ -e "\$D/over.env" ] && . "\$D/over.env"
# client modes wait for their server socket (the overlay host starts before the server)
$(case $DAEMON_KIND in
	foot) echo 'i=0; while [ ! -S "${FOOT_SOCK:-'"$T"'/run/foot.sock}" ] && [ $i -lt 100 ]; do sleep 0.1; i=$((i+1)); done' ;;
	urxvt) echo 'i=0; while [ ! -S "$RXVT_SOCKET" ] && [ $i -lt 100 ]; do sleep 0.1; i=$((i+1)); done' ;;
esac)
[ -n "\${WL_OVERRIDE:-}" ] && export WAYLAND_DISPLAY="\$WL_OVERRIDE"
[ -n "\${PRE_OVERRIDE:-}" ] && exec $PROG \$PRE_OVERRIDE "\$@"
exec $PROG $PRE "\$@"
WRAP
	chmod +x "$WRAP_PATH"
}

start_compositor() {
	mkdir -p "$T/config/cde" "$T/state" "$T/data" "$T/run" "$T/cwdtest"; chmod 700 "$T/run"
	{
		echo 'tiling {'
		echo '    terminal gap=(px)9 ring=(px)1 ring-inset=(px)4 frame="#3a3a3a"'
		echo "    terminal-args $TARGS"
		echo '}'
		echo "terminal \"$WRAP_PATH\" exec-flag=\"$EXECF\""
	} >"$T/config/cde/config.kdl"
	cat >"$T/nested.sh" <<EOF
#!/bin/sh
exec env vblank_mode=0 WAYLAND_DISPLAY=$PARENT_WL XDG_RUNTIME_DIR=$T/run XDG_STATE_HOME=$T/state XDG_CONFIG_HOME=$T/config XDG_DATA_HOME=$T/data $BIN --winit >> $T/log 2>&1
EOF
	chmod +x "$T/nested.sh"
	local r
	r=$("$BIN" msg run-on "$WS" "$T/nested.sh")
	CPID=${r#ok }
	local i
	for i in $(seq 1 100); do [ -S "$T/run/cde/wayland-1.sock" ] && break; sleep 0.2; done
	[ -S "$T/run/cde/wayland-1.sock" ] || { log "nested compositor did not come up: $r"; return 1; }
	echo "$CPID" >"$T/cpid"
	sleep 3
	if [ -n "${XD_WAIT:-}" ]; then for i in $(seq 1 50); do grep -q "XWayland ready" "$T/log" && break; sleep 0.2; done; fi
}
stop_compositor() {
	local i k
	for k in 1 2 3; do
		[ -n "${CPID:-}" ] && "$BIN" msg close-pid "$CPID" >/dev/null 2>&1 || true
		for i in $(seq 1 15); do [ -d "/proc/${CPID:-0}" ] || return 0; sleep 0.2; done
	done
	log "compositor $CPID still alive after close-pid x3; SIGTERM to that pid only"; kill "$CPID" 2>/dev/null || true
	return 0
}

# daemon/server start (warm). Sets DAEMON_PID where the mode has an explicit one
start_daemon() {
	case $DAEMON_KIND in
	foot) rm -f "$T/run/foot.sock"; env ${SERVER_DEBUG:+WAYLAND_DEBUG=1} XDG_RUNTIME_DIR=$T/run WAYLAND_DISPLAY=wayland-1 setsid "$FOOT_BIN" --server="$T/run/foot.sock" >"$T/server.out" 2>&1 </dev/null & DAEMON_PID=$!; sleep 1 ;;
	urxvt) local xd; xd=$(sed -n 's/.*XWayland ready (DISPLAY=\(:[0-9]*\)).*/\1/p' "$T/log" | tail -1)
		DISPLAY=$xd RXVT_SOCKET=$T/run/urxvtd.sock setsid "$URXVTD_BIN" -q -o >/dev/null 2>&1 & DAEMON_PID=$!; sleep 1 ;;
	cterm) DAEMON_PID="" ;; # started on demand by the first client (the overlay host)
	esac
}
find_cterm_daemon() { DAEMON_PID=$(findproc 'cterm daemon' | head -1 || true); }
# restart the foot server with/without client-protocol debug (debug only while measuring latency)
server_mode() {
	[ "$DAEMON_KIND" = foot ] || return 0
	stop_daemon; sleep 1; SERVER_DEBUG=$1
	[ "$1" = 0 ] && unset SERVER_DEBUG
	start_daemon; sleep 2
}
stop_daemon() { [ -n "${DAEMON_PID:-}" ] && kill "$DAEMON_PID" 2>/dev/null || true; DAEMON_PID=""; }

# ---- first-frame latency: compositor spawn->map line -------------------------------------------
# spawn_latency [run-in-terminal script]: spawns a terminal window, prints ms or FAIL
xcount() { DISPLAY=$DISPLAY_NESTED xwininfo -root -tree 2>/dev/null | grep -c '("urxvt" "URxvt")' || true; }
# urxvtd windows belong to the daemon, which the compositor cannot match to the spawn: poll the
# XWayland window tree instead (resolution ~ the xwininfo round trip, ~15-25 ms)
spawn_latency_x() {
	local base t0 t1 i
	base=$(xcount); t0=$(date +%s%N)
	if [ -n "${1:-}" ]; then msg run-in-terminal "$1" >/dev/null; else msg exec run-terminal >/dev/null; fi
	for i in $(seq 1 400); do
		if [ "$(xcount)" -gt "$base" ]; then t1=$(date +%s%N); echo $(((t1 - t0) / 1000000)); return 0; fi
		sleep 0.005
	done
	echo FAIL
}
# footclient windows belong to the resident foot server, not to the spawned process, so the compositor
# line cannot match them: read the server's own WAYLAND_DEBUG log (ack_configure -> attach -> commit)
spawn_latency_s() {
	local t0 i lat
	t0=$(perl -MTime::HiRes=time -e 'printf "%.6f\n", time')
	if [ -n "${1:-}" ]; then msg run-in-terminal "$1" >/dev/null; else msg exec run-terminal >/dev/null; fi
	for i in $(seq 1 100); do
		sleep 0.1
		lat=$(perl -e '
		my $t0=shift; my $best; my $M=4294967296; my $t0u=int($t0*1e6)%$M; my ($ack,$att)=(0,0);
		open(F,"<",shift) or exit; while(<F>){ next unless /^\[\s*([\d.]+)\]\s+(?:\{[^}]*\}\s+)?->\s+(\S+)\.(\w+)\((.*)\)/; my($ts,$obj,$req,$a)=($1,$2,$3,$4); my $d=($ts*1000-$t0u); $d+=$M while $d<0; $d-=$M while $d>=$M; next if $d>60e6;
		  if($req eq "ack_configure"){$ack=1} elsif($ack && $req eq "attach" && $a!~/^nil/){$att=1} elsif($att && $req eq "commit"){ $best=$d; last } }
		printf "%.1f\n",$best/1000 if defined $best' "$t0" "$T/server.out")
		[ -n "$lat" ] && { echo "$lat"; return 0; }
	done
	echo FAIL
}
spawn_latency() {
	local n0 i line
	[ "$DAEMON_KIND" = foot ] && [ "${SERVER_DEBUG:-0}" = 1 ] && { spawn_latency_s "$@"; return 0; }
	[ "$DAEMON_KIND" = urxvt ] && { spawn_latency_x "$@"; return 0; }
	n0=$(wc -l <"$T/log")
	if [ -n "${1:-}" ]; then msg run-in-terminal "$1" >/dev/null; else msg exec run-terminal >/dev/null; fi
	for i in $(seq 1 200); do
		line=$(tail -n +"$((n0 + 1))" "$T/log" | strip_ansi | grep 'spawn→map kind=Terminal' | head -1 || true)
		[ -n "$line" ] && { echo "$line" | sed 's/.*spawn_to_map_ms=//'; return 0; }
		sleep 0.05
	done
	echo FAIL
}
close_windows() { # close the n newest windows politely (focused window first), then wait
	local n=${1:-1} i
	for i in $(seq 1 "$n"); do msg exec close-window >/dev/null 2>&1 || true; sleep 0.25; done
	sleep 1
}
# window processes that belong to the run (not the overlay host), for sanity
nwin() { roots | wc -l; }

latency_series() { # latency_series <label> <runs>; spawns+closes one window per run
	local label=$1 n=$2 i v vals="" fails=0
	for i in $(seq 1 "$n"); do
		gate_load || { log "load gate gave up on $label run $i"; break; }
		v=$(spawn_latency)
		log "latency $label run $i: $v ms (load1 $(load1))"
		if [ "$v" = FAIL ]; then fails=$((fails + 1)); else vals="$vals$v"$'\n'; fi
		close_windows 1
	done
	local got; got=$(printf '%s' "$vals" | grep -c . || true)
	res "lat_${label}_ms" "$(printf '%s' "$vals" | median) (n=$got, range $(printf '%s' "$vals" | minmax), fail=$fails)"
}

# cold latency of the daemon modes: a fresh private daemon instance per run
cold_latency() {
	local i v vals="" got
	for i in $(seq 1 "$RUNS"); do
		gate_load || { log "load gate gave up on cold run $i"; break; }
		local tag=cold$i
		case $DAEMON_KIND in
		cterm) stop_daemon_all; sleep 2 ;; # no private instance possible with a grant: kill the warm daemon (its overlay host window is lost and re-created)
		foot) echo "FOOT_SOCK=$T/run/foot-$tag.sock; PRE_OVERRIDE='--server-socket=$T/run/foot-$tag.sock'; $FOOT_BIN --server=\$FOOT_SOCK >/dev/null 2>&1 </dev/null & echo \$! > $T/cold.pid" >"$T/over.env" ;;
		urxvt) echo "export RXVT_SOCKET=$T/run/urxvtd-$tag.sock; $URXVTD_BIN -q -o >/dev/null 2>&1 </dev/null & echo \$! > $T/cold.pid" >"$T/over.env" ;;
		esac
		v=$(spawn_latency)
		log "latency cold run $i: $v ms (load1 $(load1))"
		[ "$v" != FAIL ] && vals="$vals$v"$'\n'
		close_windows 1
		# stop only the private cold daemon of this run
		case $DAEMON_KIND in
		cterm) : ;;
		*) [ -f "$T/cold.pid" ] && kill "$(cat "$T/cold.pid")" 2>/dev/null || true; rm -f "$T/cold.pid" ;;
		esac
		rm -f "$T/over.env"; sleep 1
	done
	got=$(printf '%s' "$vals" | grep -c . || true)
	res lat_cold_ms "$(printf '%s' "$vals" | median) (n=$got, range $(printf '%s' "$vals" | minmax))"
}

# ---- memory + idle CPU -------------------------------------------------------------------------
mem_and_idle() {
	local base pss rss np un tk
	read -r pss rss np un tk < <(procs_now)
	base=${pss:-0}; res "pss_base_kB" "$(fmt_pss "$base" "${un:-0}" "${np:-0}") (resident daemon/server + 0 user windows)"
	local count=0 target
	for target in 1 5 10; do
		while [ "$count" -lt "$target" ]; do
			gate_load || true
			spawn_latency >/dev/null; count=$((count + 1)); sleep 1.5
		done
		sleep 2
		read -r pss rss np un tk < <(procs_now)
		local r1 per=""; for r1 in $(roots); do per="$per $r1:$(procs "$r1" | cut -d' ' -f1)"; done
		log "per-root PSS kB at $target windows:$per"
		res "pss_w${target}_kB" "$(fmt_pss "$pss" "$un" "$np") (rss ${rss} kB, ${np} procs, n=1)"
		if [ "$target" = 5 ]; then
			local t0 t1 d
			gate_load || true
			t0=$tk; sleep 60; read -r pss rss np un tk < <(procs_now); t1=$tk; d=$((t1 - t0))
			res idle_cpu_5w "$(awk -v d="$d" 'BEGIN{printf "%.3f%% of one core (%d ticks / 60 s, n=1)", d/60, d}')"
		fi
	done
	close_windows 10
}

# ---- throughput and responsiveness -------------------------------------------------------------
throughput() {
	local i vals=""
	: >"$T/thr.txt"
	for i in 1 2 3; do
		gate_load || true
		spawn_latency "$T/thr.sh" >/dev/null
		local w; for w in $(seq 1 600); do [ "$(wc -l <"$T/thr.txt" 2>/dev/null || echo 0)" -ge "$i" ] && break; sleep 0.5; done
		sleep 1.5
	done
	vals=$(awk '{printf "%.3f\n",$1/1e9}' "$T/thr.txt" 2>/dev/null || true)
	res throughput_50mb_s "$(printf '%s' "$vals" | median) (n=$(printf '%s' "$vals" | grep -c . || true), range $(printf '%s' "$vals" | minmax))"
	close_windows 3
}
loaded_latency() {
	local i vals="" v
	for i in 1 2 3; do
		gate_load || true
		rm -f "$T/flood.done"
		spawn_latency "$T/flood.sh" >/dev/null; sleep 4
		v=$(spawn_latency)
		log "latency under flood run $i: $v ms"
		[ "$v" != FAIL ] && vals="$vals$v"$'\n'
		local w; for w in $(seq 1 100); do : "$w"; [ -e "$T/flood.done" ] && break; sleep 0.5; done
		close_windows 2
	done
	res lat_loaded_ms "$(printf '%s' "$vals" | median) (n=$(printf '%s' "$vals" | grep -c . || true), range $(printf '%s' "$vals" | minmax))"
}

# ---- integration checks ------------------------------------------------------------------------
integration() {
	local r
	# exec flag, through the compositor (run-in-terminal)
	rm -f "$T/exec.ok"; msg run-in-terminal "$T/exec.sh" >/dev/null; sleep 4
	[ -e "$T/exec.ok" ] && r=pass || r="FAIL"; res int_exec_flag "$r ($EXECF through run-in-terminal)"
	close_windows 1
	# cwd flag: the terminal run directly against the nested display
	rm -f "$T/cwd.out"
	local pre="$PRE"
	[ "$DAEMON_KIND" = foot ] && pre="$PRE"
	# shellcheck disable=SC2086
	env XDG_RUNTIME_DIR="$T/run" WAYLAND_DISPLAY=wayland-1 ${EXTRA_ENV:+"$EXTRA_ENV"} ${DISPLAY_NESTED:+DISPLAY=$DISPLAY_NESTED} timeout 20 "$PROG" $pre $CWDF "$T/cwdtest" $EXECF sh "$T/exec.sh" >/dev/null 2>"$T/cwd.err" || true
	[ "$(cat "$T/cwd.out" 2>/dev/null)" = "$T/cwdtest" ] && r=pass || r="FAIL (got '$(cat "$T/cwd.out" 2>/dev/null)')"
	res int_cwd "$r ($CWDF)"
	close_windows 1
	# {gap} argument: the compositor substitutes it; the spawned terminal got it and stayed up
	spawn_latency >/dev/null; sleep 2
	local last; last=$(strip_ansi <"$T/log" | grep 'spawned program=' | tail -n 1 | sed 's/.*spawned //')
	if echo "$last" | grep -qF -- "$ARGLOG" && { [ "$DAEMON_KIND" = urxvt ] || [ -d "/proc/$(echo "$last" | sed 's/.*pid=//')" ]; }; then r=pass; else r="FAIL ($last)"; fi
	res int_gap_arg "$r (compositor spawn line: ${last:0:160}; visual padding not inspected)"
	close_windows 1
	# overlay host: the warm overlay host runs inside this terminal (pids captured before any window)
	local ovl; ovl=$(sed -n "1,${OVL_N}p" "$T/pids" | tr '\n' ' ')
	if [ -n "$(findproc 'overlay-host --socket')" ]; then r=pass; else r="FAIL (no overlay-host process in this run)"; fi
	res int_overlay_host "$r (overlay-host process alive in this run; wrapper pids: ${ovl:-none}; compositor map line, only attributable for non-resident hosts: $(strip_ansi <"$T/log" | grep -m1 'spawn→map kind=Overlay' | sed 's/.*kind=Overlay//')))"
	# restore after a nested crucible restart: a window with a non-default root comes back there
	msg root "$T/cwdtest" >/dev/null; spawn_latency >/dev/null; sleep 3; msg save >/dev/null 2>&1 || true; sleep 2
	local before; before=$(allpids)
	stop_compositor; stop_daemon_all; sleep 2
	: >"$T/log.prev"; cat "$T/log" >>"$T/log.prev"; : >"$T/log"
	start_compositor; [ "$DAEMON_KIND" != none ] && [ "$DAEMON_KIND" != cterm ] && start_daemon
	sleep 6
	local newp; newp=$(allpids | grep -vxF -f <(echo "$before") | tr '\n' ' ')
	local cwds="" p
	for p in $newp ${DAEMON_PID:-}; do
		cwds="$cwds $(cwds_of "$p")"
	done
	if echo "$cwds" | grep -qF "$T/cwdtest"; then r=pass; else r="FAIL/inconclusive (cwds: $cwds; new wrapper pids: $newp)"; fi
	res int_restore "$r (workspace saved, nested crucible restarted on the same state dir)"
}
cwds_of() {
	perl -e '
	my %k; opendir(D,"/proc"); for my $p (grep /^\d+$/, readdir D){ open(F,"<","/proc/$p/stat") or next; my $s=<F>; close F; $s=~/^\d+ \(.*\) \S (\d+)/ or next; push @{$k{$1}},$p }
	my @q=@ARGV; my %s; while(defined(my $p=shift @q)){ next if $s{$p}++; push @q,@{$k{$p}||[]}; my $l=readlink("/proc/$p/cwd"); print "$l\n" if $l }' "$@"
}
stop_daemon_all() { stop_daemon; [ "$DAEMON_KIND" = cterm ] && { local pid; for pid in $(findproc 'cterm daemon'); do kill "$pid" 2>/dev/null || true; done; }; return 0; }

# ---- one mode ----------------------------------------------------------------------------------
run_mode() {
	MODE=$1
	if [ -n "${ONLY_INTEGRATION:-}" ]; then RESEXT=int.res; LOGEXT=int.log; fi
	: >"$OUT/$MODE.${LOGEXT:-log}"; : >"$OUT/$MODE.${RESEXT:-res}"
	define_mode
	[ -f "$OUT/50mb.txt" ] || perl -e 'my $i=0; while(length($b)<52428800){ $b.="line ".$i++." the quick brown fox jumps over the lazy dog 0123456789\n" } print substr($b,0,52428800)' >"$OUT/50mb.txt"
	rm -rf "$T"; mkdir -p "$T"; : >"$T/pids"; : >"$T/argv"; : >"$T/log"
	write_wrapper
	XD_WAIT=1; DAEMON_PID=""
	local cterm_build=unknown
	cterm_build=$("$CTERM_BIN" --build 2>/dev/null || echo unknown)
	res host "$(hostname) kernel $(uname -r)"
	res governor "$(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor 2>/dev/null || echo unknown) (cpu0; all: $(sort -u /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor 2>/dev/null | tr '\n' ' '))"
	res load_start "$(cat /proc/loadavg)"
	res llama_server_resident "$(pgrep -x llama-server >/dev/null && echo "yes ($(pgrep -xc llama-server) procs)" || echo no)"
	res crucible_build "$("$BIN" --build)"
	res cterm_build "$cterm_build ($("$CTERM_BIN" --version 2>/dev/null | head -1))"
	res terminal_version "$VER"
	[ "$DAEMON_KIND" = none ] || true
	start_compositor || exit 1
	start_daemon
	sleep 4
	[ "$DAEMON_KIND" = cterm ] && find_cterm_daemon
	DISPLAY_NESTED=$(sed -n 's/.*XWayland ready (DISPLAY=\(:[0-9]*\)).*/\1/p' "$T/log" | tail -1)
	OVL_N=$(wc -l <"$T/pids")
	OVL_PIDS=""; [ "$NOWRAP" = 1 ] && OVL_PIDS=$(findproc 'cterm -o' | tr '\n' ' ')
	log "overlay host wrapper pids: $(tr '\n' ' ' <"$T/pids"); daemon pid: ${DAEMON_PID:-none}; XWayland ${DISPLAY_NESTED:-none}"
	case $DAEMON_KIND in
	urxvt) res first_frame_method "XWayland window-tree poll (xwininfo -root -tree, ~15-25 ms resolution; urxvtd windows belong to the daemon, so the compositor spawn->map line cannot match them)" ;;
	foot) res first_frame_method "cold: compositor spawn->map line (1 ms; cold server is a child of the spawn, includes server start); warm and under load: foot server WAYLAND_DEBUG (ack_configure->attach->commit, ~0.1 ms; the resident server is not a child of the spawn)" ;;
	*) res first_frame_method "compositor spawn->map line (nested crucible log, 1 ms resolution)" ;;
	esac
	# memory first: the very first window is also the first-run (cold file cache) sample, kept in the log
	if [ -n "${ONLY_INTEGRATION:-}" ]; then integration; stop_daemon_all; stop_compositor; return 0; fi
	[ "$DAEMON_KIND" != none ] && cold_latency
	[ "$DAEMON_KIND" = cterm ] && { spawn_latency >/dev/null; sleep 1; close_windows 1; find_cterm_daemon; log "warm cterm daemon pid ${DAEMON_PID:-NOT FOUND}"; }
	server_mode 1
	latency_series warm "$RUNS"
	[ -n "${QUICK:-}" ] && { stop_daemon_all; stop_compositor; return 0; }
	loaded_latency
	server_mode 0
	mem_and_idle
	throughput
	integration
	res discarded_samples "$DISCARDS wait rounds (load1 > $LOAD_MAX, waited 10 s and repeated); samples taken anyway after the wait limit: $LOAD_OVER_ACCEPTED"
	res load_end "$(cat /proc/loadavg)"
	stop_daemon_all; stop_compositor
	log "== $MODE done"
	[ -n "${KEEP:-}" ] || rm -rf "$T"
}

# ---- table -------------------------------------------------------------------------------------
table() {
	local d=${1:-$OUT} m k
	for k in lat_cold_ms lat_warm_ms pss_base_kB pss_w1_kB pss_w5_kB pss_w10_kB idle_cpu_5w throughput_50mb_s lat_loaded_ms int_exec_flag int_cwd int_gap_arg int_overlay_host int_restore terminal_version discarded_samples; do
		echo "### $k"
		for m in $MODES; do [ -f "$d/$m.res" ] && printf -- '- %s: %s\n' "$m" "$(grep -m1 "^$k=" "$d/$m.res" | cut -d= -f2-)"; done
	done
}

case "${1:-}" in
'') usage >&2; exit 2 ;;
table) shift; table "$@"; exit 0 ;;
esac
mkdir -p "$OUT"
exec 9>"$OUT/lock"
flock -n 9 || { echo "another matrix run holds $OUT/lock; waiting" >&2; flock 9; }
for m in "$@"; do run_mode "$m"; done
